import React from 'react';
import ReactDOM from 'react-dom';
import DataTable, {
  TableContainer,
  Table,
  TableHead,
  TableBody,
  TableRow,
  TableHeader,
  TableCell,
  TableExpandHeader,
  TableExpandRow,
  TableExpandedRow,
} from 'carbon-components-react';

// Minimal sample data
tconst headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];
const rows = [
  { id: 'row-1', name: 'Load Balancer 1', status: 'Active' },
  { id: 'row-2', name: 'Load Balancer 2', status: 'Disabled' },
];

function ExpansionTableExample() {
  return (
    <DataTable rows={rows} headers={headers}>
      {({ rows, headers, getHeaderProps, getTableProps, getRowProps, getTableContainerProps }) => (
        <TableContainer
          title="DataTable"
          description="With expansion"
          {...getTableContainerProps()}>
          <Table {...getTableProps()}>
            <TableHead>
              <TableRow>
                {/* we pass an id here, but it isn’t rendered onto the <th> */}
                <TableExpandHeader id="expand" />
                {headers.map((header) => (
                  <TableHeader key={header.key} {...getHeaderProps({ header })}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row) => (
                <React.Fragment key={row.id}>
                  <TableExpandRow expandHeader="expand" {...getRowProps({ row })}>
                    {row.cells.map((cell) => (
                      <TableCell key={cell.id}>{cell.value}</TableCell>
                    ))}
                  </TableExpandRow>
                  <TableExpandedRow colSpan={headers.length + 1}>
                    Expanded content for {row.id}
                  </TableExpandedRow>
                </React.Fragment>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </DataTable>
  );
}

ReactDOM.render(<ExpansionTableExample />, document.getElementById('root'));
